insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) values ('che-ek-274', 'chemistry-electrochemistry-and-chemical-kinetics', 'chemistry', 'For a reaction between a solid and a gas or liquid, grinding the solid into a powder', '["raises the rate by exposing a larger surface","lowers the rate because grains are smaller","changes the stoichiometric equation","removes the need for a collision"]'::jsonb, 0, 'Heterogeneous rates scale with the available surface. A powder offers far more area than a single lump of equal mass.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb, 'easy', 'rate-factors') on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
