insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) values ('che-ek-280', 'chemistry-electrochemistry-and-chemical-kinetics', 'chemistry', 'A gas-phase reaction is first order in A. Doubling the partial pressure of A at constant $T$ and then raising $T$ so that $k$ also doubles will multiply the rate by', '["4","2","1","8"]'::jsonb, 0, 'First-order rate $= k[\mathrm{A}]$. Doubling [A] (via $p_A$) doubles the rate; doubling $k$ doubles it again, so the net factor is 4.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb, 'hard', 'rate-factors') on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
